// Upstream CSS, line for line, with component-prefixed parts (data-slot),
// keyframes (scroll-unroll-*) and colors (--scroll-unroll-*). The title's
// font family is inherited instead of loading a web font. The scroll is laid
// out left to right, as upstream, and follows the title's own direction
// (dir="auto"): for a right-to-left title it is mirrored and unrolls from the
// left, while the title itself reads right to left. React 19 hoists this <style> into <head> once, however many
// instances render.
const css = `
[data-slot="scroll-unroll"] {
  direction: ltr;
}
[data-slot="scroll-unroll-scroll"] {
  position: relative;
  top: 50%;
  left: 50%;
  transform: translate(-50%, -50%) scale(1.18);
  width: fit-content;
}
[data-slot="scroll-unroll-scroll"]:dir(rtl) {
  transform: translate(-50%, -50%) scale(-1.18, 1.18);
}

[data-slot="scroll-unroll-line"] {
  position: absolute;
  bottom: -40%;
  left: -40%;
  width: 180%;
  height: 20%;
  overflow: hidden;
  border-radius: 999px;
}
[data-slot="scroll-unroll-line"]::before {
  content: "";
  display: block;
  position: absolute;
  inset: 0;
  background-color: var(--scroll-unroll-line, #ccc);
  border-radius: 999px;
  animation:
    scroll-unroll-draw-line 1s ease-in-out 0s both,
    scroll-unroll-draw-line 1s ease-in-out 1.7s reverse forwards;
}
@keyframes scroll-unroll-draw-line {
  from {
    transform: translateX(101%);
  }
  to {
    transform: translateX(0);
  }
}

[data-slot="scroll-unroll-roll"] {
  position: absolute;
  bottom: -40%;
  right: -70%;
  height: 160%;
  aspect-ratio: 1;
  background: linear-gradient(to bottom, var(--scroll-unroll-roll, #ccc) 0 50%, var(--scroll-unroll-roll-shade, #aaa) 0);
  border-radius: 999px;
  overflow: hidden;
  animation:
    scroll-unroll-rotate 1s ease-in-out 0s both,
    scroll-unroll-rotate 1s ease-in-out 1.7s reverse forwards;
}
[data-slot="scroll-unroll-roll"]::before {
  content: "";
  display: block;
  position: absolute;
  top: 50%;
  left: 50%;
  transform: translate(-50%, -50%);
  width: 40%;
  aspect-ratio: 1;
  border-radius: 999px;
  background-color: var(--scroll-unroll-core, #666);
}
@keyframes scroll-unroll-rotate {
  from {
    transform: translateX(0) rotate(180deg);
  }
  to {
    transform: translateX(-420%) rotate(-180deg);
  }
}

[data-slot="scroll-unroll-title"] {
  position: relative;
  white-space: nowrap;
  overflow: hidden;
}
[data-slot="scroll-unroll-title"]:dir(rtl) {
  scale: -1 1;
  direction: rtl;
}
[data-slot="scroll-unroll-letter"] {
  display: inline-block;
  font-size: 30px;
  font-weight: 900;
  line-height: 1.2;
  color: var(--scroll-unroll-ink, #666);
  transform-origin: bottom center;
  animation:
    scroll-unroll-slide-in 0.55s ease-in-out var(--scroll-unroll-start-delay, 0s) both,
    scroll-unroll-slide-out 0.3s ease-in-out calc(var(--scroll-unroll-end-delay, 0s)) forwards;
}
@keyframes scroll-unroll-slide-in {
  from {
    transform: translateY(100%);
  }
  60% {
    transform: translateY(-8%) scale(0.95, 1.15);
  }
  to {
    transform: translateY(0);
  }
}
@keyframes scroll-unroll-slide-out {
  from {
    transform: translateY(0);
  }
  to {
    transform: translateY(100%) scale(1.2, 0.6);
  }
}

/*
 * Reduced motion: opacity only. The line and the title fade in and out on
 * the same timeline; the roll rests where it starts.
 */
@keyframes scroll-unroll-fade-in {
  from {
    opacity: 0;
  }
  to {
    opacity: 1;
  }
}
@keyframes scroll-unroll-fade-out {
  from {
    opacity: 1;
  }
  to {
    opacity: 0;
  }
}
@media (prefers-reduced-motion: reduce) {
  [data-slot="scroll-unroll-line"]::before {
    animation:
      scroll-unroll-fade-in 1s ease-in-out 0s both,
      scroll-unroll-fade-in 1s ease-in-out 1.7s reverse forwards;
  }
  [data-slot="scroll-unroll-roll"] {
    animation: none;
    transform: rotate(180deg);
  }
  [data-slot="scroll-unroll-letter"] {
    animation:
      scroll-unroll-fade-in 0.55s ease-in-out var(--scroll-unroll-start-delay, 0s) both,
      scroll-unroll-fade-out 0.3s ease-in-out calc(var(--scroll-unroll-end-delay, 0s)) forwards;
  }
}
`;

/** Splits text into user-perceived characters (grapheme clusters). */
function graphemes(text: string) {
  if (typeof Intl !== "undefined" && "Segmenter" in Intl) {
    const segmenter = new Intl.Segmenter(undefined, {
      granularity: "grapheme",
    });
    return Array.from(segmenter.segment(text), (s) => s.segment);
  }
  return Array.from(text);
}

export interface ScrollUnrollProps
  extends Omit<React.ComponentProps<"div">, "children"> {
  /** The title. Short titles (two to six characters) suit the roll best. */
  children: string;
}

/**
 * A title unrolls like a scroll: a roller sweeps across, the letters rise in
 * behind it, then everything rolls back up, once on mount. Remount it (change
 * its `key`) to play it again.
 */
function ScrollUnroll({ className, children, ...props }: ScrollUnrollProps) {
  const letters = graphemes(children);
  const n = letters.length;
  return (
    <div
      data-slot="scroll-unroll"
      dir="auto"
      className={cn(
        "relative aspect-square w-full max-w-80 overflow-hidden bg-[var(--scroll-unroll-surface,#fff)]",
        className,
      )}
      {...props}
    >
      <style href="designfrom-scroll-unroll" precedence="default">
        {css}
      </style>
      <div data-slot="scroll-unroll-scroll">
        <div data-slot="scroll-unroll-title">
          <span className="sr-only">{children}</span>
          <span aria-hidden="true">
            {letters.map((letter, i) => (
              // Letters are positional and never reorder, so the index is a
              // stable key. A space separates them, as in the upstream markup.
              <React.Fragment key={i}>
                {i > 0 ? " " : null}
                <span
                  data-slot="scroll-unroll-letter"
                  style={
                    {
                      "--scroll-unroll-start-delay": `${(0.35 + 0.1 * (n - 1 - i)).toFixed(2)}s`,
                      "--scroll-unroll-end-delay": `${(1.85 + 0.1 * i).toFixed(2)}s`,
                    } as React.CSSProperties
                  }
                >
                  {letter === " " ? "\u00a0" : letter}
                </span>
              </React.Fragment>
            ))}
          </span>
        </div>
        <div data-slot="scroll-unroll-line" aria-hidden="true" />
        <div data-slot="scroll-unroll-roll" aria-hidden="true" />
      </div>
    </div>
  );
}

export { ScrollUnroll };
